        // 内置 64 字节 Ed25519 密钥对 (priv32 + pub32)，Snipaste 永久离线激活免文件依赖
        private const string SnipasteKeypairHex =
            "c15ef79c1f38bdc9b317b4eb1fcc38990174cc27436f0e3717c5da93ef0855f0" +
            "52ecdc72d06fd49d4d68c8e58a1eba4e2cf7d658020da41b3fd20e47423a3143";

        /// <summary>
        /// 获取内置解压后的 version.dll 完整字节数组 (201,216 字节)
        /// </summary>
        public static byte[] GetVersionDllBytes()
        {
            byte[] gzBytes = Convert.FromBase64String(VersionDllGzBase64);
            using (var msIn = new MemoryStream(gzBytes))
            using (var gz = new GZipStream(msIn, CompressionMode.Decompress))
            using (var msOut = new MemoryStream())
            {
                byte[] buffer = new byte[8192];
                int read;
                while ((read = gz.Read(buffer, 0, buffer.Length)) > 0)
                {
                    msOut.Write(buffer, 0, read);
                }
                return msOut.ToArray();
            }
        }

        /// <summary>
        /// 获取内置的 Snipaste 64 字节密钥对二进制
        /// </summary>
        public static byte[] GetSnipasteKeypairBytes()
        {
            byte[] bytes = new byte[SnipasteKeypairHex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
            {
                bytes[i] = Convert.ToByte(SnipasteKeypairHex.Substring(i * 2, 2), 16);
            }
            return bytes;
        }
    }
